<?php
$editId=(int)($_GET['edit']??0);$edit=null;if($editId){$s=db()->prepare('SELECT * FROM categories WHERE id=?');$s->execute([$editId]);$edit=$s->fetch();}
$edit=$edit?:['id'=>0,'parent_id'=>'','name'=>'','slug'=>'','icon'=>'','image'=>'','description'=>'','sort_order'=>0,'show_in_menu'=>1,'is_active'=>1,'meta_title'=>'','meta_description'=>'','meta_keywords'=>''];
$cats=db()->query("SELECT c.*,p.name parent_name,(SELECT COUNT(*) FROM products x WHERE x.category_id=c.id) product_count FROM categories c LEFT JOIN categories p ON p.id=c.parent_id ORDER BY COALESCE(c.parent_id,0),c.sort_order,c.name")->fetchAll();
?>
